-- S2-T04: auth subset of the schema (ARCHITECTURE section 10, ADR-024, ADR-025).
-- Plain, portable PostgreSQL 16. No provider-specific features. S4-T01 extends this schema.
-- Primary keys are uuid (v7) generated by the application. Timestamps are timestamptz in UTC.

create table organizations (
    id               uuid primary key,
    external_auth_id text,
    name             text not null,
    status           text not null default 'active' check (status in ('active', 'suspended')),
    created_at       timestamptz not null default now()
);

-- Reserved for Clerk (Next phase, NP-02).
create unique index organizations_external_auth_id_key
    on organizations (external_auth_id) where external_auth_id is not null;

create table users (
    id         uuid primary key,
    email      text not null unique check (email = lower(email)),
    name       text not null,
    status     text not null default 'active' check (status in ('active', 'disabled')),
    created_at timestamptz not null default now()
);

create table memberships (
    tenant_id uuid not null references organizations (id) on delete cascade,
    user_id   uuid not null references users (id) on delete cascade,
    role      text not null check (role in ('owner', 'admin', 'developer', 'billing')),
    primary key (tenant_id, user_id)
);

create index memberships_user_id_idx on memberships (user_id);

-- Single use, 15 minute expiry. Only the SHA-256 hash of the token is stored.
create table login_tokens (
    id         uuid primary key,
    user_id    uuid not null references users (id) on delete cascade,
    token_hash bytea not null unique,
    expires_at timestamptz not null,
    used_at    timestamptz,
    issued_by  text not null
);

-- Server-side sessions. The cookie carries a random token; only its SHA-256 hash is stored.
-- created_at is added to the ARCHITECTURE column list: operator actions need a fresh session.
create table sessions (
    id          uuid primary key,
    user_id     uuid not null references users (id) on delete cascade,
    tenant_id   uuid not null references organizations (id) on delete cascade,
    token_hash  bytea not null unique,
    csrf_secret bytea not null,
    expires_at  timestamptz not null,
    revoked_at  timestamptz,
    created_at  timestamptz not null default now()
);

create index sessions_user_id_idx on sessions (user_id);
